FAILED_RESULT_SHA = '88ae0114989ce02b940f9b89aa1109b341e18f1b4545a671a4defed0cde3ba5d'
CRYPTO_ROOT = '/data1/home/sunyiq/zhenjiang_crypto_transport_20260916_001'
