def crypto_platform():
    actual = {"python": platform.python_version(), "implementation": platform.python_implementation(),
              "system": platform.system(), "machine": platform.machine()}
    libc, version = platform.libc_ver()
    if (actual != CRYPTO_PLATFORM or libc != "glibc" or not re.fullmatch(r"\d+\.\d+(\.\d+)?", version)
            or tuple(map(int, version.split("."))) < (2, 17) or sys.executable != PYTHON):
        raise ValueError("exact registered Python/platform required")
    return dict(actual, libc=libc, libc_version=version)

def crypto_owned(path):
    path = safe_path(path)
    if path.stat().st_uid != os.getuid():
        raise ValueError("dependency owner differs")
    return path

def crypto_roots(absent=False):
    parent = crypto_owned(Path(CRYPTO_PARENT))
    root, evaluation = safe_path(Path(CRYPTO_ROOT)), safe_path(Path(REMOTE))
    if root.parent != parent or evaluation.parent != parent or not parent.is_dir():
        raise ValueError("private roots/parent differ")
    if absent and (root.exists() or evaluation.exists()):
        raise FileExistsError("private dependency or evaluation root exists")
    if not absent:
        crypto_owned(root)
        if not root.is_dir() or stat.S_IMODE(root.stat().st_mode) != 0o700:
            raise ValueError("private root permissions differ")
    return root

def crypto_inventory(site):
    site = crypto_owned(site)
    if not site.is_dir():
        raise ValueError("installed site missing")
    rows, total = [], 0
    for path in sorted(site.rglob("*")):
        crypto_owned(path)
        if path.is_dir():
            continue
        relative = safe_name(path.relative_to(site).as_posix())
        raw = read_regular(path, CRYPTO_MAX_BYTES)
        total += len(raw)
        rows.append({"path": relative, "size_bytes": len(raw), "sha256": sha(raw)})
        if len(rows) > CRYPTO_MAX_FILES or total > CRYPTO_MAX_BYTES:
            raise ValueError("installed inventory bounds")
    if not rows:
        raise ValueError("empty installed site")
    return {"files": rows, "total_files": len(rows), "total_bytes": total}

def crypto_modules(site):
    """Only process-local sys.path; no environment export to any child job."""
    site = crypto_owned(site)
    names = (*CRYPTO_VERSIONS, "_cffi_backend")
    def origin(module):
        filename = getattr(module, "__file__", None)
        if type(filename) is not str or site not in crypto_owned(Path(filename)).parents:
            raise ValueError("dependency module origin differs")
    for name, module in list(sys.modules.items()):
        if any(name == key or name.startswith(key + ".") for key in names):
            origin(module)
    distributions = list(importlib.metadata.distributions(path=[str(site)]))
    versions = [(item.metadata["Name"], item.version) for item in distributions]
    if len(versions) != 3 or dict(versions) != CRYPTO_VERSIONS:
        raise ValueError("installed distribution metadata differs")
    sys.dont_write_bytecode = True
    sys.path.insert(0, str(site))
    importlib.invalidate_caches()
    for name in names:
        module = importlib.import_module(name)
        origin(module)
        expected = CRYPTO_MODULE_VERSIONS[name]
        if getattr(module, "__version__", None) != expected:
            raise ValueError("dependency version differs")
        if name == "_cffi_backend" and not module.__file__.endswith(".so"):
            raise ValueError("native backend location differs")
    crypto, SHA256, serialization, OAEP, MGF1, rsa, AESGCM = crypto_imports()
    key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
    padding = OAEP(mgf=MGF1(algorithm=SHA256()), algorithm=SHA256(), label=None)
    plaintext = b"temporal dependency self-check"
    if key.decrypt(key.public_key().encrypt(plaintext, padding), padding) != plaintext:
        raise ValueError("RSA dependency self-check failed")
    aes = AESGCM(bytes(range(32)))
    nonce, aad = bytes(range(12)), b"synthetic-only"
    if aes.decrypt(nonce, aes.encrypt(nonce, plaintext, aad), aad) != plaintext:
        raise ValueError("AES dependency self-check failed")
    for name, module in list(sys.modules.items()):
        if any(name == key or name.startswith(key + ".") for key in names):
            origin(module)

def crypto_validate_receipt(receipt):
    keys = {"schema", "auth_sha256", "wheel_manifest_sha256", "dependency_root", "pysite", "owner_uid",
            "platform", "versions", "inventory_sha256", "total_files", "total_bytes"}
    if type(receipt) is not dict or set(receipt) != keys:
        raise ValueError("dependency receipt schema differs")
    expected = {"schema": "zhenjiang-crypto-dependency-receipt-v1", "auth_sha256": AUTH_SHA,
                "wheel_manifest_sha256": WHEELS_SHA, "dependency_root": CRYPTO_ROOT,
                "pysite": CRYPTO_ROOT + "/pysite", "versions": CRYPTO_VERSIONS}
    if any(type(receipt[k]) is not type(v) or receipt[k] != v for k, v in expected.items()):
        raise ValueError("dependency receipt identity differs")
    if (type(receipt["owner_uid"]) is not int or receipt["owner_uid"] < 0
            or type(receipt["total_files"]) is not int or not 0 < receipt["total_files"] <= CRYPTO_MAX_FILES
            or type(receipt["total_bytes"]) is not int or not 0 < receipt["total_bytes"] <= CRYPTO_MAX_BYTES
            or type(receipt["inventory_sha256"]) is not str or not re.fullmatch("[0-9a-f]{64}", receipt["inventory_sha256"])):
        raise ValueError("dependency receipt count/digest differs")
    value = receipt["platform"]
    if (type(value) is not dict or set(value) != set(CRYPTO_PLATFORM) | {"libc", "libc_version"}
            or any(type(v) is not str for v in value.values())
            or any(value[k] != v for k, v in CRYPTO_PLATFORM.items()) or value["libc"] != "glibc"
            or not re.fullmatch(r"\d+\.\d+(\.\d+)?", value["libc_version"])
            or tuple(map(int, value["libc_version"].split("."))) < (2, 17)):
        raise ValueError("dependency receipt platform differs")
    return receipt

def crypto_activate(receipt):
    crypto_validate_receipt(receipt)
    if crypto_platform() != receipt["platform"]:
        raise ValueError("dependency runtime changed")
    root = crypto_roots()
    evaluation = crypto_owned(Path(REMOTE))
    if not evaluation.is_dir() or stat.S_IMODE(evaluation.stat().st_mode) != 0o700:
        raise ValueError("prepared evaluation root permissions differ")
    if root.stat().st_uid != receipt["owner_uid"]:
        raise ValueError("dependency receipt owner differs")
    for path in root.rglob("*"):
        crypto_owned(path)
    saved = read_regular(root / "receipt.json", 20000)
    inventory_raw = read_regular(root / "inventory.json", 2_000_000)
    current = crypto_inventory(root / "pysite")
    if (saved != canonical(receipt) or sha(inventory_raw) != receipt["inventory_sha256"]
            or canonical(current) != inventory_raw or current["total_files"] != receipt["total_files"]
            or current["total_bytes"] != receipt["total_bytes"]):
        raise ValueError("installed dependency inventory changed")
    crypto_modules(root / "pysite")
    if canonical(crypto_inventory(root / "pysite")) != inventory_raw:
        raise ValueError("dependency import changed installed inventory")

def crypto_documents(auth_raw, wheels_raw):
    """Raw SHA identities precede parsing; validate exact field types as well."""
    if (type(auth_raw) is not bytes or type(wheels_raw) is not bytes
            or len(auth_raw) > 20000 or len(wheels_raw) > 20000
            or sha(auth_raw) != AUTH_SHA or sha(wheels_raw) != WHEELS_SHA):
        raise ValueError("pinned authority or wheel manifest changed")
    auth, wheels = document(auth_raw), document(wheels_raw)
    strings = {"schema", "authorization_id", "user_utterance", "authorization_context", "experiment_id",
               "remote_evaluation_root", "remote_dependency_root", "execution_contract_raw_sha256",
               "local_preparation_directory", "private_install_target", "dependency_exposure"}
    integers = {"successor_preparation_sequence", "maximum_new_preparation_attempts", "maximum_private_install_calls",
                "private_install_timeout_seconds", "maximum_total_sbatch_submissions", "remaining_sbatch_submissions",
                "source_extraction_retries", "formal_reads_before_verified_preparation"}
    booleans = {"install_offline", "build_from_source", "change_shared_environment", "automatic_retry",
                "scientific_contract_changes", "preserve_failed_attempt"}
    if type(auth) is not dict or set(auth) != strings | integers | booleans | {"failed_predecessor", "resource_budget"}:
        raise ValueError("authority schema differs")
    for keys, kind in ((strings, str), (integers, int), (booleans, bool)):
        if any(type(auth[k]) is not kind for k in keys):
            raise ValueError("authority field type differs")
    previous = auth["failed_predecessor"]
    expected_previous = {"sequence": 110, "command_sha256": FAILED_COMMAND_SHA, "result_sha256": FAILED_RESULT_SHA,
                         "result_bytes": 400, "exit_code": 1, "error": "ModuleNotFoundError: No module named 'cryptography'"}
    if (type(previous) is not dict or set(previous) != set(expected_previous)
            or any(type(previous[k]) is not type(v) or previous[k] != v for k, v in expected_previous.items())):
        raise ValueError("failed predecessor authority differs")
    budget = auth["resource_budget"]
    if type(budget) is not dict or set(budget) != {"gpus", "cpus", "hours"} or any(
            type(budget[k]) is not int or budget[k] != v for k, v in {"gpus": 1, "cpus": 4, "hours": 1}.items()):
        raise ValueError("resource authority differs")
    if (auth["schema"] != "zhenjiang-crypto-successor-authorization-v1"
            or auth["remote_dependency_root"] != CRYPTO_ROOT or auth["remote_evaluation_root"] != REMOTE
            or auth["execution_contract_raw_sha256"] != CONTRACT_SHA or auth["successor_preparation_sequence"] != 111
            or auth["local_preparation_directory"] != "c2/preparation_002"):
        raise ValueError("successor authority identity differs")
    if (type(wheels) is not dict or set(wheels) != {"schema", "purpose", "platform", "total_bytes", "packages"}
            or any(type(wheels[k]) is not str for k in ("schema", "purpose", "platform"))
            or wheels["schema"] != "zhenjiang-crypto-wheels-v1" or type(wheels["total_bytes"]) is not int
            or wheels["total_bytes"] != 4976224 or type(wheels["packages"]) is not list or len(wheels["packages"]) != 3):
        raise ValueError("wheel schema differs")
    seen, aliases, filenames = set(), set(), set()
    keys = {"name", "version", "local_basename", "filename", "size_bytes", "sha256", "url", "metadata_url", "requires", "yanked"}
    for row in wheels["packages"]:
        if (type(row) is not dict or set(row) != keys
                or any(type(row[k]) is not str for k in keys - {"size_bytes", "requires", "yanked"})
                or type(row["size_bytes"]) is not int or not 0 < row["size_bytes"] <= 5_000_000
                or type(row["requires"]) is not list or any(type(v) is not str for v in row["requires"])
                or row["yanked"] is not False or not re.fullmatch("[0-9a-f]{64}", row["sha256"])
                or CRYPTO_VERSIONS.get(row["name"]) != row["version"]):
            raise ValueError("wheel field differs")
        for key in ("filename", "local_basename"):
            if safe_name(row[key]) != Path(row[key]).name or "/" in row[key] or not row[key].endswith(".whl"):
                raise ValueError("wheel basename differs")
        if row["name"] in seen or row["filename"] in filenames or row["local_basename"] in aliases:
            raise ValueError("duplicate wheel")
        seen.add(row["name"]); filenames.add(row["filename"]); aliases.add(row["local_basename"])
    if seen != set(CRYPTO_VERSIONS) or sum(r["size_bytes"] for r in wheels["packages"]) != wheels["total_bytes"]:
        raise ValueError("wheel set or total differs")
    return auth, wheels

def crypto_payload(wheels, payload):
    if type(payload) is not dict or set(payload) != {r["filename"] for r in wheels["packages"]}:
        raise ValueError("wheel payload set differs")
    result = {}
    for row in wheels["packages"]:
        encoded = payload[row["filename"]]
        if type(encoded) is not str or len(encoded) > (row["size_bytes"] + 2) // 3 * 4:
            raise ValueError("wheel payload bounds")
        raw = base64.b64decode(encoded, validate=True)
        if len(raw) != row["size_bytes"] or sha(raw) != row["sha256"]:
            raise ValueError("embedded wheel differs")
        result[row["filename"]] = raw
    if sum(map(len, result.values())) != wheels["total_bytes"]:
        raise ValueError("wheel payload total differs")
    return result

def crypto_pip_process(argv, *, cwd, env, capture_output, check, timeout):
    """One Linux subprocess; deadline and both output buffers are bounded."""
    if capture_output is not True or check is not False or timeout != 180:
        raise ValueError("private pip process contract differs")
    buffers = {"stdout": bytearray(), "stderr": bytearray()}
    process = subprocess.Popen(argv, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                               stdin=subprocess.DEVNULL)
    try:
        deadline = time.monotonic() + timeout
        with selectors.DefaultSelector() as selector:
            for name in buffers:
                stream = getattr(process, name)
                os.set_blocking(stream.fileno(), False)
                selector.register(stream, selectors.EVENT_READ, name)
            while selector.get_map():
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise subprocess.TimeoutExpired(argv, timeout)
                for event, _ in selector.select(min(remaining, 0.5)):
                    chunk = os.read(event.fileobj.fileno(), 65536)
                    if not chunk:
                        selector.unregister(event.fileobj)
                        continue
                    buffer = buffers[event.data]
                    available = CRYPTO_LOG_LIMIT - len(buffer)
                    buffer.extend(chunk[:available])
                    if len(chunk) > available:
                        raise ValueError("pip output limit exceeded; process stopped")
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise subprocess.TimeoutExpired(argv, timeout)
        code = process.wait(timeout=remaining)
        return subprocess.CompletedProcess(argv, code, bytes(buffers["stdout"]), bytes(buffers["stderr"]))
    except BaseException as error:
        if process.poll() is None:
            process.kill()
        process.wait(timeout=5)
        error.stdout, error.stderr = bytes(buffers["stdout"]), bytes(buffers["stderr"])
        error.pip_returncode = process.returncode
        raise
    finally:
        process.stdout.close()
        process.stderr.close()

def crypto_install(auth_raw, wheels_raw, payload, run=None):
    """Exactly one offline pip call, and failure artifacts remain private forever."""
    auth, wheels = crypto_documents(auth_raw, wheels_raw)
    actual_platform = crypto_platform()
    root = crypto_roots(absent=True)
    decoded = crypto_payload(wheels, payload)
    root.mkdir(mode=0o700, exist_ok=False)
    for name in ("wheels", "tmp", "cache", "logs", "pysite", "attempt"):
        (root / name).mkdir(mode=0o700, exist_ok=False)
    for filename, raw in decoded.items():
        write_new(root / "wheels" / filename, raw, root)
    argv = [PYTHON, "-B", "-m", "pip", "--isolated", "--disable-pip-version-check", "--no-cache-dir",
            "install", "--no-input", "--no-index", "--no-deps", "--only-binary=:all:", "--no-compile",
            "--ignore-installed", "--target", str(root / "pysite")]
    argv += [str(root / "wheels" / row["filename"]) for row in wheels["packages"]]
    environment = dict(os.environ)
    for key in list(environment):
        if key.startswith("PIP_") or key in ("PYTHONPATH", "PYTHONHOME"):
            environment.pop(key)
    environment.update(TMPDIR=str(root / "tmp"), TMP=str(root / "tmp"), TEMP=str(root / "tmp"),
                       XDG_CACHE_HOME=str(root / "cache"), PYTHONPYCACHEPREFIX=str(root / "cache"),
                       PYTHONDONTWRITEBYTECODE="1")
    put(root / "attempt/requested.json", {"argv": argv, "auth_sha256": AUTH_SHA,
        "wheel_manifest_sha256": WHEELS_SHA, "maximum_calls": 1, "timeout_seconds": 180}, root)
    run = crypto_pip_process if run is None else run
    try:
        response = run(argv, cwd=root, env=environment, capture_output=True, check=False, timeout=180)
        stdout, stderr, code = response.stdout, response.stderr, response.returncode
        if type(stdout) is not bytes or type(stderr) is not bytes or type(code) is not int:
            raise ValueError("pip response types differ")
        write_new(root / "logs/stdout.txt", stdout[:CRYPTO_LOG_LIMIT], root)
        write_new(root / "logs/stderr.txt", stderr[:CRYPTO_LOG_LIMIT], root)
        put(root / "logs/exit.json", {"returncode": code, "stdout_bytes": len(stdout), "stderr_bytes": len(stderr)}, root)
        if len(stdout) > CRYPTO_LOG_LIMIT or len(stderr) > CRYPTO_LOG_LIMIT:
            raise ValueError("pip log bounds exceeded; retained bounded evidence")
        if code != 0:
            raise RuntimeError("private pip failed; no retry")
        inventory = crypto_inventory(root / "pysite")
        crypto_modules(root / "pysite")
        if crypto_inventory(root / "pysite") != inventory:
            raise ValueError("dependency self-check changed installed files")
        inventory_raw = canonical(inventory)
        if len(inventory_raw) > 2_000_000:
            raise ValueError("inventory serialization bounds")
        receipt = {"schema": "zhenjiang-crypto-dependency-receipt-v1", "auth_sha256": AUTH_SHA,
                   "wheel_manifest_sha256": WHEELS_SHA, "dependency_root": str(root), "pysite": CRYPTO_ROOT + "/pysite",
                   "owner_uid": root.stat().st_uid, "platform": actual_platform, "versions": dict(CRYPTO_VERSIONS),
                   "inventory_sha256": sha(inventory_raw), "total_files": inventory["total_files"],
                   "total_bytes": inventory["total_bytes"]}
        crypto_validate_receipt(receipt)
        write_new(root / "inventory.json", inventory_raw, root)
        put(root / "receipt.json", receipt, root)
        return receipt
    except BaseException as error:
        for name in ("stdout", "stderr"):
            target = root / "logs" / (name + ".txt")
            if not target.exists():
                raw = getattr(error, name, b"") or b""
                write_new(target, raw[:CRYPTO_LOG_LIMIT], root)
        if not (root / "logs/exit.json").exists():
            put(root / "logs/exit.json", {"returncode": getattr(error, "pip_returncode", None),
                "timeout_seconds": 180 if isinstance(error, subprocess.TimeoutExpired) else None,
                "error_type": type(error).__name__}, root)
        put(root / "attempt/failure.json", {"error_type": type(error).__name__, "status": "stopped_no_retry"}, root)
        raise


